#[cfg(test)] mod tests{
 use super::*;
 #[test]
 fn five_way_switch_has_checked_zero_padding(){
  let f=fragment();assert_eq!(f.code.len(),INSTRUCTION_COUNT+1);
  let b=super::super::extension6_disjoint::emit(&f).unwrap();
  assert_eq!(b.len(),FILE_END-FILE_START);
  assert_eq!(&b[0xdfa0-FILE_START..0xdfa6-FILE_START],&[6,6,6,118,118,0]);
  assert!(FIVE_WAY_TARGETS.iter().all(|target|target%2==0));
 }
}
